function sameIdSet(a: readonly string[], b: readonly string[]): boolean {
  if (a.length !== b.length) return false;
  const left = [...a].sort();
  const right = [...b].sort();
  return left.every((id, index) => id === right[index]);
}

mutations.after:
function sameIdSet(a: readonly string[], b: readonly string[]): boolean {
  return a === b;
}

